    "stem": "A 44-year-old man is evaluated during rapid triage in the emergency resuscitation bay with clinical findings indicative of Cardiogenic Shock Post-Myocardial Infarction Hypotension. Clinical examination and investigative review confirm intra-aortic balloon pump (IABP) or Impella mechanical circulatory support and emergent coronary revascularization. Vitals reveal blood pressure of 132/82 mm Hg, heart rate of 68/min, respiratory rate of 16/min, and temperature of 38.2C (98.7F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of cardiogenic shock post-myocardial infarction hypotension. Which acute algorithmic intervention must be performed without delay in accordance with Royal College of Emergency Medicine protocols?",
